            reader.read_log_rows(ids.as_deref()).unwrap()
        })
        .collect();
    actual.sort_by_key(|row| (row.block_number, row.log_index));
    assert_eq!(actual, expected);
    assert_eq!(storage.total_rows(), expected.len() as u64);
}

